// ═══ STRATEGY 1: IMMUTABLE — best! Zero synchronization needed ═══
public record TradeConfirmation(
    String tradeId, String symbol, BigDecimal amount, LocalDateTime timestamp
) {
    // ALL fields are final (record = implicitly final fields)
    // No setters. No mutable state. Share freely between threads!
    // String, BigDecimal, LocalDateTime are all immutable.
}
// 100 threads can read this simultaneously — zero risk!

// ═══ STRATEGY 2: CONFINEMENT — state never shared ═══
// Stack confinement:
public TradeResult processTrade(TradeRequest request) {
    BigDecimal localAmount = request.amount();  // LOCAL variable — on this thread's stack!
    BigDecimal fee = localAmount.multiply(new BigDecimal("0.001"));
    return new TradeResult(localAmount.subtract(fee));
    // localAmount and fee are NEVER visible to other threads!
}

// ThreadLocal confinement:
private static final ThreadLocal<SimpleDateFormat> dateFormatter =
    ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));
// Each thread gets its OWN SimpleDateFormat instance. No sharing!
// SimpleDateFormat is NOT thread-safe, but ThreadLocal makes it safe.

// ═══ STRATEGY 3: DELEGATION — use thread-safe building blocks ═══
public class TradeCache {
    // Delegate to ConcurrentHashMap — thread-safe by design!
    private final ConcurrentHashMap<String, Trade> cache = new ConcurrentHashMap<>();

    // Delegate to AtomicLong — thread-safe counter!
    private final AtomicLong tradeCount = new AtomicLong(0);

    public void addTrade(Trade trade) {
        cache.put(trade.getId(), trade);
        tradeCount.incrementAndGet();  // atomic!
    }

    public Trade getTrade(String id) {
        return cache.get(id);  // lock-free read!
    }
    // ZERO synchronized blocks! All thread safety delegated to ConcurrentHashMap + AtomicLong.
}

// ═══ STRATEGY 4: LOCKING — last resort, most error-prone ═══
public class AccountService {
    private final Object lock = new Object();  // PRIVATE FINAL lock!
    private BigDecimal balance;                 // guarded by 'lock'
    private String lastTransactionId;           // guarded by 'lock'

    public void debit(String txnId, BigDecimal amount) {
        synchronized (lock) {
            // ALL shared state access inside ONE lock!
            if (balance.compareTo(amount) < 0)
                throw new InsufficientFundsException(balance, amount);
            balance = balance.subtract(amount);
            lastTransactionId = txnId;
        }
    }
    // Rules:
    // 1. Lock is PRIVATE (no external code can lock on it → no deadlock)
    // 2. Lock is FINAL (can't be reassigned → always the same lock)
    // 3. ALL shared state guarded by the SAME lock consistently
    // 4. Critical section is SMALL (only read-modify-write)
}

// ═══ ANTI-PATTERNS ═══
// ❌ synchronized(this) → external code can lock on your object → deadlock!
// ❌ synchronized(new Object()) → NEW object each time → NO synchronization!
// ❌ Lock not final: lock = new Object() → reassigned → different lock!
// ❌ Leaking 'this' in constructor → thread sees partially-constructed object!
// ❌ Publishing internal mutable state: return internalList; → caller modifies!
