package com.bank.threadsafe;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ThreadSafeDesignTest {

    // ═══ STRATEGY 1: IMMUTABLE record ═══
    record TradeConfirmation(String tradeId, BigDecimal amount, LocalDateTime time) {}

    @Test
    void immutable_safeByDesign() throws InterruptedException {
        TradeConfirmation confirmation = new TradeConfirmation(
            "TRD-001", new BigDecimal("50000"), LocalDateTime.now());

        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);
        Set<String> ids = ConcurrentHashMap.newKeySet();

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                // 50 threads read the SAME immutable object — zero risk!
                ids.add(confirmation.tradeId());
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(ids).containsExactly("TRD-001");  // always consistent!
    }

    // ═══ STRATEGY 2: ThreadLocal confinement ═══
    private static final ThreadLocal<List<String>> threadLog =
        ThreadLocal.withInitial(ArrayList::new);

    @Test
    void confinement_threadLocal() throws InterruptedException {
        int threads = 5;
        CountDownLatch latch = new CountDownLatch(threads);
        AtomicInteger sizes = new AtomicInteger(0);

        for (int i = 0; i < threads; i++) {
            final int threadId = i;
            new Thread(() -> {
                // Each thread gets its OWN ArrayList!
                threadLog.get().add("Entry-" + threadId);
                sizes.addAndGet(threadLog.get().size());
                threadLog.remove();  // cleanup!
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(sizes.get()).isEqualTo(5);  // each thread added 1 entry to ITS OWN list
    }

    // ═══ STRATEGY 3: Delegation to thread-safe classes ═══
    @Test
    void delegation_concurrentHashMapAndAtomic() throws InterruptedException {
        ConcurrentHashMap<String, BigDecimal> balances = new ConcurrentHashMap<>();
        AtomicInteger txnCount = new AtomicInteger(0);

        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            final int id = i;
            new Thread(() -> {
                balances.put("ACC-" + id, new BigDecimal(id * 1000));
                txnCount.incrementAndGet();
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(balances).hasSize(100);
        assertThat(txnCount.get()).isEqualTo(100);  // zero synchronization code!
    }

    // ═══ STRATEGY 4: Private final lock ═══
    static class LockedAccount {
        private final Object lock = new Object();
        private int balance;

        LockedAccount(int balance) { this.balance = balance; }

        void debit(int amount) {
            synchronized (lock) {
                if (balance >= amount) balance -= amount;
            }
        }

        int getBalance() {
            synchronized (lock) { return balance; }
        }
    }

    @Test
    void locking_privateFinalLock() throws InterruptedException {
        LockedAccount account = new LockedAccount(100000);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> { account.debit(1000); latch.countDown(); }).start();
        }
        latch.await();
        assertThat(account.getBalance()).isEqualTo(0);
    }

    // ═══ ANTI-PATTERN: leaking mutable state ═══
    @Test
    void antiPattern_leakingMutableState() {
        List<String> internal = new ArrayList<>(List.of("TXN-001"));
        List<String> defensiveCopy = List.copyOf(internal);  // immutable copy!

        internal.add("TXN-002");
        assertThat(internal).hasSize(2);
        assertThat(defensiveCopy).hasSize(1);  // copy not affected!
    }
}
